-- Official Brazilian municipal keys; source dataset references IBGE municipality codes.
create table if not exists public.entre_official_cities (
 state_code text not null, city_key text not null, city_name text not null, ibge_code text not null,
 primary key(state_code,city_key)
);
alter table public.entre_official_cities enable row level security;
revoke all on public.entre_official_cities from public,anon,authenticated;
